package com.jetbrains.mcpkts.codegen

import io.modelcontextprotocol.kotlin.sdk.types.Tool
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.jsonPrimitive
import java.util.Locale

object McpCodeGenerator {
    /** Nobody edits the generated file, so IDE warnings about it are noise. */
    private val SUPPRESSED_INSPECTIONS = listOf(
        "unused",
        "UnusedImport",
        "MemberVisibilityCanBePrivate",
        "FunctionName",
        "ClassName",
        "PropertyName",
        "EnumEntryName",
        "SpellCheckingInspection",
        "KDocUnresolvedReference",
    ).joinToString(separator = ", ") { "\"$it\"" }

    fun bindingsFileName(serverName: String): String = "${toPascalCase(serverName, "Mcp")}Bindings.mcp.kts"

    fun bindingsClassName(serverName: String): String = "${toPascalCase(serverName, "Mcp")}Bindings"

    fun generate(
        serverName: String,
        serverUrl: String,
        serverHeaders: Map<String, String> = emptyMap(),
        serverEnvHeaders: Map<String, String> = emptyMap(),
        tools: List<Tool>,
    ): String {
        val generator = Generator(
            serverName = serverName,
            serverUrl = serverUrl,
            serverHeaders = serverHeaders,
            serverEnvHeaders = serverEnvHeaders,
        )
        return generator.generate(tools)
    }

    private class Generator(
        private val serverName: String,
        private val serverUrl: String,
        private val serverHeaders: Map<String, String>,
        /** Header name to the environment variable its value is read from at call time. */
        private val serverEnvHeaders: Map<String, String>,
    ) {
        private val typeNames = UniqueNames()
        private val functionNames = UniqueNames()
        private val declarations = linkedMapOf<String, Declaration>()
        private val constantNames = UniqueNames()
        private val toolConstants = linkedMapOf<String, String>()
        private val headerConstants = linkedMapOf<String, HeaderConstant>()
        private val bindingsClassName = bindingsClassName(serverName)

        fun generate(tools: List<Tool>): String {
            allocateConstants(tools)
            val functions = tools.map { tool -> renderFunction(tool) }
            val renderedDeclarations = declarations.values.map { declaration ->
                declaration.render().prependIndent("    ")
            }
            val source = buildString {
                appendLine("@file:Suppress($SUPPRESSED_INSPECTIONS)")
                appendLine()
                appendLine("import com.jetbrains.mcpkts.McpJsonSupport")
                appendLine("import com.jetbrains.mcpkts.McpResult")
                appendLine("import com.jetbrains.mcpkts.McpRuntime")
                appendLine("import kotlinx.serialization.json.JsonElement")
                appendLine("import kotlinx.serialization.json.JsonObject")
                appendLine("import kotlinx.serialization.json.JsonPrimitive")
                appendLine("import kotlinx.serialization.json.buildJsonArray")
                appendLine("import kotlinx.serialization.json.buildJsonObject")
                appendLine()
                appendLine("// generated by mcp-kts")
                appendLine("class $bindingsClassName {")
                append(renderConstants().prependIndent("    "))
                appendLine()
                appendLine()
                if (renderedDeclarations.isNotEmpty()) {
                    append(renderedDeclarations.joinToString(separator = "\n\n"))
                    appendLine()
                    appendLine()
                }
                if (functions.isNotEmpty()) {
                    append(functions.joinToString(separator = "\n\n") { it.prependIndent("    ") })
                    appendLine()
                }
                appendLine("}")
            }

            return source
        }

        private fun renderFunction(tool: Tool): String {
            // Distinct tool names can collapse onto the same camelCase identifier
            // (e.g. "get_user" and "get-user"); keep the emitted functions unique.
            val functionName = escapeIdentifier(functionNames.allocate(toCamelCase(tool.name, "callTool")))
            val toolBaseName = toPascalCase(tool.name, "Tool")
            val inputSchema = tool.inputSchema
            val paramNames = UniqueNames()
            // Empty when the schema declares no properties: the tool then takes a raw `args` object.
            val params = inputSchema.properties.orEmpty().entries.map { (wireName, schemaElement) ->
                Field(
                    wireName = wireName,
                    renderedName = escapeIdentifier(paramNames.allocate(toCamelCase(wireName, "value"))),
                    type = resolveType(
                        schema = schemaElement.asJsonObjectOrNull(),
                        suggestedName = toolBaseName + "Input" + toPascalCase(wireName, "Value"),
                        forInput = true,
                    ),
                    required = inputSchema.required.orEmpty().contains(wireName),
                    description = schemaDescription(schemaElement.asJsonObjectOrNull()),
                )
            }

            val returnType = resolveReturnType(tool, toolBaseName)
            val functionKdoc = renderKdoc(
                summary = tool.description?.takeIf { it.isNotBlank() }?.trim()
                    ?: tool.title?.takeIf { it.isNotBlank() }?.trim(),
                tags = params.mapNotNull { parameter ->
                    parameter.description?.let { "@param ${parameter.renderedName} $it" }
                },
            )
            val renderedParams = if (params.isEmpty()) {
                "args: JsonObject = buildJsonObject { }"
            } else {
                params.joinToString(", ") { parameter -> parameter.render() }
            }

            val callArguments = if (params.isEmpty()) {
                "args"
            } else {
                buildString {
                    appendLine("buildJsonObject {")
                    params.forEach { parameter ->
                        val encodedValue = parameter.type.encodeExpression(parameter.renderedName)
                        if (parameter.required) {
                            appendLine("            put(\"${escapeString(parameter.wireName)}\", $encodedValue)")
                        } else {
                            appendLine("            ${parameter.renderedName}?.let { put(\"${escapeString(parameter.wireName)}\", ${parameter.type.encodeExpression("it")}) }")
                        }
                    }
                    append("        }")
                }
            }

            val callExpression = buildString {
                appendLine("McpRuntime.call(")
                appendLine("            serverName = $SERVER_NAME_CONSTANT,")
                appendLine("            url = $SERVER_URL_CONSTANT,")
                appendLine("            headers = $HEADERS_CONSTANT,")
                if (serverEnvHeaders.isNotEmpty()) appendLine("            envHeaders = $ENV_HEADERS_CONSTANT,")
                appendLine("            tool = ${toolConstants.getValue(tool.name)},")
                appendLine("            args = $callArguments,")
                append("        )")
            }

            return buildString {
                if (functionKdoc.isNotEmpty()) {
                    appendLine(functionKdoc)
                }
                append("fun $functionName($renderedParams): ${returnType?.renderedType(nullable = false) ?: "McpResult"}")
                appendLine(" {")
                if (returnType == null) {
                    appendLine("        return $callExpression")
                } else {
                    appendLine("        val result = $callExpression")
                    appendLine(
                        "        return ${returnType.decodeExpression("result.requireStructuredContent(\"${escapeString(serverName)}.${escapeString(tool.name)}\")", "\"structuredContent\"")}",
                    )
                }
                append("    }")
            }
        }

        /** Null when the tool declares no structured output: the function then returns the raw `McpResult`. */
        private fun resolveReturnType(tool: Tool, toolBaseName: String): TypeRef? {
            val outputSchema = tool.outputSchema ?: return null
            val properties = outputSchema.properties
            if (properties.isNullOrEmpty()) {
                return null
            }
            return resolveObjectType(
                properties = properties,
                required = outputSchema.required.orEmpty().toSet(),
                suggestedName = toolBaseName + "Result",
                forInput = false,
            )
        }

        /**
         * [forInput] says which way values of the type travel: input types are only ever encoded,
         * output types only decoded, so each declaration gets just the helper it needs.
         */
        private fun resolveType(
            schema: JsonObject?,
            suggestedName: String,
            forInput: Boolean,
        ): TypeRef {
            if (schema == null) {
                return JsonElementType
            }

            val enumValues = schema["enum"].asStringEnumOrNull()
            if (enumValues != null) {
                return resolveEnumType(
                    values = enumValues,
                    suggestedName = suggestedName,
                    forInput = forInput,
                )
            }

            val type = schema["type"].typeName()
            return when (type) {
                "string" -> StringType
                "integer" -> IntType
                "number" -> DoubleType
                "boolean" -> BooleanType
                "array" -> {
                    val itemType = resolveType(
                        schema = schema["items"].asJsonObjectOrNull(),
                        suggestedName = suggestedName + "Item",
                        forInput = forInput,
                    )
                    ListType(itemType)
                }

                else -> {
                    val properties = schema["properties"].asJsonObjectOrNull()
                    when {
                        !properties.isNullOrEmpty() -> resolveObjectType(
                            properties = properties,
                            required = schema["required"].asStringListOrEmpty().toSet(),
                            suggestedName = suggestedName,
                            forInput = forInput,
                        )
                        type == "object" -> JsonObjectType
                        else -> JsonElementType
                    }
                }
            }
        }

        private fun resolveObjectType(
            properties: JsonObject,
            required: Set<String>,
            suggestedName: String,
            forInput: Boolean,
        ): TypeRef {
            val typeName = typeNames.allocate(toPascalCase(suggestedName, "GeneratedObject"))
            val propertyNames = UniqueNames()
            val objectProperties = properties.entries.map { (wireName, schemaElement) ->
                Field(
                    wireName = wireName,
                    renderedName = escapeIdentifier(propertyNames.allocate(toCamelCase(wireName, "value"))),
                    type = resolveType(
                        schema = schemaElement.asJsonObjectOrNull(),
                        suggestedName = typeName + toPascalCase(wireName, "Value"),
                        forInput = forInput,
                    ),
                    required = required.contains(wireName),
                    description = schemaDescription(schemaElement.asJsonObjectOrNull()),
                )
            }
            declarations[typeName] = ObjectDeclaration(
                name = typeName,
                properties = objectProperties,
                forInput = forInput,
            )
            return NamedType(typeName)
        }

        private fun resolveEnumType(
            values: List<String>,
            suggestedName: String,
            forInput: Boolean,
        ): TypeRef {
            val typeName = typeNames.allocate(toPascalCase(suggestedName, "GeneratedEnum"))
            declarations[typeName] = EnumDeclaration(
                name = typeName,
                values = values,
                forInput = forInput,
            )
            return EnumType(typeName)
        }

        /**
         * Allocated up front because [renderFunction] needs the names, and via [UniqueNames] because
         * distinct wire names can collapse (`get_user` and `get-user` both want TOOL_GET_USER).
         */
        private fun allocateConstants(tools: List<Tool>) {
            listOf(SERVER_NAME_CONSTANT, SERVER_URL_CONSTANT, HEADERS_CONSTANT, ENV_HEADERS_CONSTANT)
                .forEach(constantNames::allocate)
            tools.forEach { tool ->
                toolConstants.getOrPut(tool.name) {
                    constantNames.allocate("TOOL_" + toConstantName(tool.name, "TOOL"))
                }
            }
            serverHeaders.keys.sorted().forEach { name ->
                val keyConstant = constantNames.allocate("HEADER_" + toConstantName(name, "HEADER"))
                headerConstants[name] = HeaderConstant(
                    keyConstant = keyConstant,
                    valueConstant = constantNames.allocate(keyConstant + "_VALUE"),
                )
            }
        }

        private fun renderConstants(): String = buildString {
            appendLine("companion object {")
            appendLine("    const val $SERVER_NAME_CONSTANT = \"${escapeString(serverName)}\"")
            appendLine("    const val $SERVER_URL_CONSTANT = \"${escapeString(serverUrl)}\"")
            headerConstants.forEach { (name, constant) ->
                appendLine()
                appendLine("    const val ${constant.keyConstant} = \"${escapeString(name)}\"")
                val value = escapeString(serverHeaders.getValue(name))
                appendLine("    const val ${constant.valueConstant} = \"$value\"")
            }
            appendLine()
            if (headerConstants.isEmpty()) {
                appendLine("    val $HEADERS_CONSTANT: Map<String, String> = emptyMap()")
            } else {
                appendLine("    val $HEADERS_CONSTANT: Map<String, String> = mapOf(")
                headerConstants.values.forEach { constant ->
                    appendLine("        ${constant.keyConstant} to ${constant.valueConstant},")
                }
                appendLine("    )")
            }
            if (serverEnvHeaders.isNotEmpty()) {
                appendLine()
                appendLine("    val $ENV_HEADERS_CONSTANT: Map<String, String> = mapOf(")
                serverEnvHeaders.toSortedMap().forEach { (name, variable) ->
                    appendLine("        \"${escapeString(name)}\" to \"${escapeString(variable)}\",")
                }
                appendLine("    )")
            }
            toolConstants.forEach { (wireName, constant) ->
                appendLine()
                appendLine("    const val $constant = \"${escapeString(wireName)}\"")
            }
            append("}")
        }
    }

    private fun schemaDescription(schema: JsonObject?): String? =
        schema?.get("description")?.stringValue()?.takeIf { it.isNotBlank() }?.trim()

    private fun renderKdoc(summary: String?, tags: List<String>): String {
        val summaryLines = summary?.let(::sanitizeKdoc)?.lines().orEmpty().dropWhile { it.isBlank() }
        val tagLines = tags.map(::sanitizeKdoc)
        if (summaryLines.isEmpty() && tagLines.isEmpty()) {
            return ""
        }
        return buildString {
            appendLine("/**")
            summaryLines.forEach { line ->
                appendLine(if (line.isBlank()) " *" else " * $line")
            }
            if (summaryLines.isNotEmpty() && tagLines.isNotEmpty()) {
                appendLine(" *")
            }
            tagLines.forEach { line -> appendLine(" * $line") }
            append(" */")
        }
    }

    private fun sanitizeKdoc(text: String): String =
        text.replace("\r\n", "\n")
            .replace("\r", "\n")
            // Both markers: Kotlin block comments nest, so a stray "/*" (any glob like "src/**")
            // opens a comment that never closes and swallows the rest of the file.
            .replace("/*", "&#47;*")
            .replace("*/", "*&#47;")
            .trimEnd()

    /** A function parameter or a data class property. */
    private data class Field(
        val wireName: String,
        val renderedName: String,
        val type: TypeRef,
        val required: Boolean,
        val description: String?,
    ) {
        fun render(): String =
            "$renderedName: ${type.renderedType(nullable = !required)}" + if (required) "" else " = null"
    }

    private sealed interface Declaration {
        fun render(): String
    }

    private data class ObjectDeclaration(
        val name: String,
        val properties: List<Field>,
        val forInput: Boolean,
    ) : Declaration {
        override fun render(): String {
            val constructor = properties.joinToString(",\n") { property -> "    val ${property.render()}" }

            val encoder = buildString {
                appendLine("private fun encode$name(value: $name): JsonObject = buildJsonObject {")
                properties.forEach { property ->
                    if (property.required) {
                        appendLine(
                            "    put(\"${escapeString(property.wireName)}\", ${property.type.encodeExpression("value.${property.renderedName}")})",
                        )
                    } else {
                        appendLine(
                            "    value.${property.renderedName}?.let { put(\"${escapeString(property.wireName)}\", ${property.type.encodeExpression("it")}) }",
                        )
                    }
                }
                append("}")
            }

            val decoder = buildString {
                appendLine("private fun decode$name(json: JsonObject, path: String): $name {")
                appendLine("    return $name(")
                append(
                    properties.joinToString(",\n") { property ->
                        val valueExpression = if (property.required) {
                            property.type.decodeExpression(
                                "McpJsonSupport.required(json, \"${escapeString(property.wireName)}\")",
                                "path + \".${escapeString(property.wireName)}\"",
                            )
                        } else {
                            val access = "json[\"${escapeString(property.wireName)}\"]"
                            val decoded = property.type.decodeExpression("it", "path + \".${escapeString(property.wireName)}\"")
                            // An untyped JsonElement decodes to itself, so `?.let { it }` is a no-op;
                            // emit the nullable accessor directly in that case.
                            if (decoded == "it") access else "$access?.let { $decoded }"
                        }

                        "        ${property.renderedName} = $valueExpression"
                    },
                )
                appendLine()
                appendLine("    )")
                append("}")
            }

            val classKdoc = renderKdoc(
                summary = null,
                tags = properties.mapNotNull { property ->
                    property.description?.let { "@property ${property.renderedName} $it" }
                },
            )
            return buildString {
                if (classKdoc.isNotEmpty()) {
                    appendLine(classKdoc)
                }
                appendLine("data class $name(")
                append(constructor)
                appendLine()
                appendLine(")")
                appendLine()
                append(if (forInput) encoder else decoder)
            }
        }
    }

    private data class EnumDeclaration(
        val name: String,
        val values: List<String>,
        val forInput: Boolean,
    ) : Declaration {
        override fun render(): String {
            // Distinct wire values can collapse onto one entry identifier ("read"/"READ");
            // keep entries unique while preserving the wire value.
            val entryNames = UniqueNames()
            val enumValues = values.joinToString(",\n") { value ->
                "    ${entryNames.allocate(renderEnumEntry(value))}(\"${escapeString(value)}\")"
            }

            return buildString {
                appendLine("enum class $name(val wireValue: String) {")
                append(enumValues)
                appendLine(";")
                appendLine()
                appendLine("    companion object {")
                appendLine("        fun fromWireValue(wireValue: String): $name {")
                appendLine("            return entries.firstOrNull { it.wireValue == wireValue }")
                appendLine("                ?: error(\"Unknown $name value '${'$'}wireValue'.\")")
                appendLine("        }")
                appendLine("    }")
                append("}")
                if (!forInput) {
                    appendLine()
                    appendLine()
                    appendLine("private fun decode$name(element: JsonElement, path: String): $name {")
                    appendLine("    return $name.fromWireValue(McpJsonSupport.asString(element, path))")
                    append("}")
                }
            }
        }
    }

    private sealed interface TypeRef {
        fun renderedType(nullable: Boolean): String

        fun encodeExpression(expression: String): String

        fun decodeExpression(expression: String, pathExpression: String): String
    }

    private data object StringType : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable("String", nullable)


        override fun encodeExpression(expression: String): String = "JsonPrimitive($expression)"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "McpJsonSupport.asString($expression, $pathExpression)"
    }

    private data object IntType : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable("Int", nullable)


        override fun encodeExpression(expression: String): String = "JsonPrimitive($expression)"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "McpJsonSupport.asInt($expression, $pathExpression)"
    }

    private data object DoubleType : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable("Double", nullable)


        override fun encodeExpression(expression: String): String = "JsonPrimitive($expression)"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "McpJsonSupport.asDouble($expression, $pathExpression)"
    }

    private data object BooleanType : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable("Boolean", nullable)


        override fun encodeExpression(expression: String): String = "JsonPrimitive($expression)"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "McpJsonSupport.asBoolean($expression, $pathExpression)"
    }

    private data object JsonObjectType : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable("JsonObject", nullable)


        override fun encodeExpression(expression: String): String = expression

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "McpJsonSupport.asObject($expression, $pathExpression)"
    }

    private data object JsonElementType : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable("JsonElement", nullable)


        override fun encodeExpression(expression: String): String = expression

        override fun decodeExpression(expression: String, pathExpression: String): String = expression
    }

    private data class NamedType(
        val name: String,
    ) : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable(name, nullable)


        override fun encodeExpression(expression: String): String = "encode$name($expression)"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "decode$name(McpJsonSupport.asObject($expression, $pathExpression), $pathExpression)"
    }

    private data class EnumType(
        val name: String,
    ) : TypeRef {
        override fun renderedType(nullable: Boolean): String = renderNullable(name, nullable)


        override fun encodeExpression(expression: String): String = "JsonPrimitive($expression.wireValue)"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "decode$name($expression, $pathExpression)"
    }

    private data class ListType(
        val itemType: TypeRef,
    ) : TypeRef {
        override fun renderedType(nullable: Boolean): String =
            renderNullable("List<${itemType.renderedType(nullable = false)}>", nullable)


        override fun encodeExpression(expression: String): String =
            "buildJsonArray { $expression.forEach { item -> add(${itemType.encodeExpression("item")}) } }"

        override fun decodeExpression(expression: String, pathExpression: String): String =
            "McpJsonSupport.asArray($expression, $pathExpression).mapIndexed { index, item -> ${itemType.decodeExpression("item", "$pathExpression + \"[\" + index + \"]\"")} }"
    }

    private class UniqueNames {
        private val used = mutableSetOf<String>()

        fun allocate(baseName: String): String {
            var candidate = baseName
            var index = 2
            while (!used.add(candidate)) {
                candidate = "$baseName$index"
                index += 1
            }
            return candidate
        }
    }

    private data class HeaderConstant(val keyConstant: String, val valueConstant: String)

    /** SCREAMING_SNAKE_CASE from the raw wire name, so separators survive: `X-Trace` -> `X_TRACE`. */
    private fun toConstantName(value: String, fallback: String): String {
        val snake = value
            .replace(Regex("([a-z0-9])([A-Z])"), "$1_$2")
            .replace(Regex("[^A-Za-z0-9]+"), "_")
            .uppercase(Locale.ROOT)
            .trim('_')
        return when {
            snake.isEmpty() -> fallback.uppercase(Locale.ROOT)
            snake.first().isDigit() -> "_$snake"
            else -> snake
        }
    }

    private const val SERVER_NAME_CONSTANT = "SERVER_NAME"
    private const val SERVER_URL_CONSTANT = "SERVER_URL"
    private const val HEADERS_CONSTANT = "HEADERS"
    private const val ENV_HEADERS_CONSTANT = "ENV_HEADERS"

    private fun renderEnumEntry(value: String): String {
        val entry = toPascalCase(value, "Value")
        val uppercase = entry.replace(Regex("([a-z0-9])([A-Z])"), "$1_$2").uppercase(Locale.ROOT)
        return if (uppercase.firstOrNull()?.isDigit() == true) {
            "_$uppercase"
        } else {
            uppercase
        }
    }

    private fun toCamelCase(value: String, fallback: String): String {
        val parts = splitIdentifierParts(value)
        val combined = if (parts.isEmpty()) {
            fallback
        } else {
            buildString {
                append(parts.first().lowercase(Locale.ROOT))
                parts.drop(1).forEach { part ->
                    append(part.lowercase(Locale.ROOT).replaceFirstChar { character ->
                        character.titlecase(Locale.ROOT)
                    })
                }
            }
        }
        return normalizeIdentifier(combined, fallback)
    }

    private fun toPascalCase(value: String, fallback: String): String {
        val parts = splitIdentifierParts(value)
        val combined = if (parts.isEmpty()) {
            fallback
        } else {
            parts.joinToString(separator = "") { part ->
                part.lowercase(Locale.ROOT).replaceFirstChar { character ->
                    character.titlecase(Locale.ROOT)
                }
            }
        }
        return normalizeTypeName(combined, fallback)
    }

    private fun splitIdentifierParts(value: String): List<String> {
        val normalized = value.replace(Regex("([a-z0-9])([A-Z])"), "$1 $2")
        return normalized.split(Regex("[^A-Za-z0-9]+"))
            .filter { it.isNotBlank() }
    }

    /** [value] is ASCII letters and digits already; only a leading digit needs fixing. */
    private fun normalizeIdentifier(value: String, fallback: String): String {
        return if (value.first().isDigit()) {
            fallback + value
        } else {
            value
        }
    }

    private fun normalizeTypeName(value: String, fallback: String): String {
        val identifier = normalizeIdentifier(value, fallback)
        return identifier.replaceFirstChar { character ->
            character.titlecase(Locale.ROOT)
        }
    }

    private fun escapeIdentifier(identifier: String): String {
        return if (identifier in KOTLIN_KEYWORDS) {
            "`$identifier`"
        } else {
            identifier
        }
    }

    private fun renderNullable(typeName: String, nullable: Boolean): String {
        return if (nullable) "$typeName?" else typeName
    }

    private fun JsonElement?.asJsonObjectOrNull(): JsonObject? = this as? JsonObject

    private fun JsonElement?.asStringListOrEmpty(): List<String> {
        return (this as? JsonArray)
            ?.mapNotNull { element -> element.jsonPrimitive.contentOrNull }
            .orEmpty()
    }

    private fun JsonElement?.asStringEnumOrNull(): List<String>? {
        return (this as? JsonArray)
            ?.map { element -> (element as? JsonPrimitive)?.takeIf { it.isString }?.content ?: return null }
    }

    private fun JsonElement?.stringValue(): String? = (this as? JsonPrimitive)?.contentOrNull

    /**
     * Resolves a JSON Schema `type` to a single type name. Besides a plain `"integer"`, servers
     * commonly express an optional field as a nullable union such as `["integer", "null"]`; in that
     * case we keep the single non-null member so the property still gets a concrete Kotlin type
     * instead of falling back to a raw JsonElement.
     */
    private fun JsonElement?.typeName(): String? {
        return when (this) {
            is JsonPrimitive -> contentOrNull
            is JsonArray -> {
                mapNotNull { (it as? JsonPrimitive)?.contentOrNull }
                    .filter { it != "null" }
                    .distinct()
                    .singleOrNull()
            }

            else -> null
        }
    }

    private fun escapeString(value: String): String = buildString {
        value.forEach { character ->
            when (character) {
                '\\' -> append("\\\\")
                '"' -> append("\\\"")
                '$' -> append("\\$")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> if (character < ' ') append("\\u%04x".format(character.code)) else append(character)
            }
        }
    }

    private val KOTLIN_KEYWORDS = setOf(
        "as",
        "break",
        "class",
        "continue",
        "do",
        "else",
        "false",
        "for",
        "fun",
        "if",
        "in",
        "interface",
        "is",
        "null",
        "object",
        "package",
        "return",
        "super",
        "this",
        "throw",
        "true",
        "try",
        "typealias",
        "typeof",
        "val",
        "var",
        "when",
        "while",
    )
}
